	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.invoiceSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Invoice : " + successValue.getInvoiceId());
							  if (successValue.getInvoiceId().equals(invoiceId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfInvoiceList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Invoice test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on invoice consumed")
					);
			subscriber.invoiceSubscribe( invoiceId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Invoice : " + successValue.getInvoiceId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfInvoiceList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on invoice for invoiceId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Invoice. 
	 */
	protected Invoice read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Invoice" );

		Invoice entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Invoice with primary key" );
		msg.append( invoiceId );
		
		InvoiceFetchOneSummary fetchOneSummary = new InvoiceFetchOneSummary( invoiceId );

		try {
			entity = InvoiceService.getInvoiceInstance().getInvoice( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Invoice " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Invoice.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Invoice." );

		StringBuilder msg = new StringBuilder( "Failed to update a Invoice : " );        
		Invoice entity = read();
		UpdateInvoiceCommand command = generateUpdateCommand();
		command.setInvoiceId(entity.getInvoiceId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Invoice." );

			// for use later on...
			invoiceId = entity.getInvoiceId();

			InvoiceService proxy = InvoiceService.getInvoiceInstance();  

			proxy.updateInvoice( command ).get();

			LOGGER.info( "-- Successfully saved Invoice - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + invoiceId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Invoice.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Invoice." );

		Invoice entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Invoice with id " + invoiceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Invoice with id " + invoiceId );

			throw e;
		}

		try{
			InvoiceService.getInvoiceInstance().delete( new DeleteInvoiceCommand( entity.getInvoiceId() ) ).get();
			LOGGER.info( "-- Successfully deleted Invoice with id " + invoiceId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Invoice with id " + invoiceId );

			throw e;
		}
	}

	/**
	 * get all Invoices.
	 */
	protected List<Invoice> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Invoices:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Invoice : " );        
		List<Invoice> collection  = new ArrayList<>();

		try {
			// call the static get method on the InvoiceService
			collection = InvoiceService.getInvoiceInstance().getAllInvoice();
			assertNotNull( collection, "An Empty collection of Invoice was incorrectly returned.");
			
			// Now print out the values
			Invoice entity = null;            
			Iterator<Invoice> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getInvoiceId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

